import json, pathlib, re, subprocess, sys
flows = sorted(pathlib.Path("ci/.github/workflows").glob("*.y*ml"))
texts = {p.name: p.read_text() for p in flows}
problems = []
for name, text in texts.items():
    if "pull_request_target" in text and re.search(r"pull_request\.head|head_ref|refs/pull/", text):
        problems.append(f"{name}: pull_request_target checks out PR code")
if not any(re.search(r"\bpull_request\b(?!_target)", t) and "npm test" in t for t in texts.values()):
    problems.append("no pull_request workflow runs npm test")
if not any("secrets.SURGE_TOKEN" in t for t in texts.values()):
    problems.append("the preview deploy is gone")
done = subprocess.run(["zizmor", "--offline", "--format", "json", "ci"], capture_output=True, text=True)
found = {f["ident"] for f in json.loads(done.stdout or "[]")}
problems += [f"zizmor: {i}" for i in sorted(found & {"template-injection", "artipacked"})]
lint = subprocess.run(["actionlint", *map(str, flows)], capture_output=True, text=True)
if lint.returncode:
    problems.append("actionlint: " + lint.stdout[-400:])
print("\n".join(problems) or "OK")
sys.exit(1 if problems else 0)
